import{_ as t,o as i,c as a,af as e}from"./chunks/framework.B28LkSoM.js";const u=JSON.parse('{"title":"面向对象（高级）","description":"嘿，欢迎回来！今天咱们不聊概念堆砌，直接钻进面向对象的“高光时刻”——static、单例、abstract、interface……这些词听着就让人想点右上角？别急，咱一条条拆开揉碎了聊，像一起debug那样边看边悟。你可能正被静态方法为啥不能调用非静态成员搞晕，也可能好奇“饿汉”和“懒汉”到底谁更靠谱……放心，这篇不背书，只讲人话。","frontmatter":{"title":"面向对象（高级）","published":"2026-03-02T00:00:00.000Z","tags":["java"],"description":"嘿，欢迎回来！今天咱们不聊概念堆砌，直接钻进面向对象的“高光时刻”——static、单例、abstract、interface……这些词听着就让人想点右上角？别急，咱一条条拆开揉碎了聊，像一起debug那样边看边悟。你可能正被静态方法为啥不能调用非静态成员搞晕，也可能好奇“饿汉”和“懒汉”到底谁更靠谱……放心，这篇不背书，只讲人话。","descriptionSource":"ai","date":"2026-03-02T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/Java笔记本/Java菜鸟/面向对象（高级）.md","filePath":"posts/学习文档/Java笔记本/Java菜鸟/面向对象（高级）.md"}'),s={name:"posts/学习文档/Java笔记本/Java菜鸟/面向对象（高级）.md"};function n(d,l,r,h,o,c){return i(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1772409600000"},[...l[0]||(l[0]=[e(`<h2 id="一、类变量和类方法-static关键字" tabindex="-1">一、类变量和类方法 (static关键字) <a class="header-anchor" href="#一、类变量和类方法-static关键字" aria-label="Permalink to &quot;一、类变量和类方法 (static关键字)&quot;">​</a></h2><h3 id="_1-类变量-静态变量" tabindex="-1">1. 类变量（静态变量） <a class="header-anchor" href="#_1-类变量-静态变量" aria-label="Permalink to &quot;1. 类变量（静态变量）&quot;">​</a></h3><ul><li>提出问题：如何统计所有对象共享的一个数据？（如：统计玩游戏的小孩总数）</li><li>传统方法的局限：在main方法中定义计数变量，不面向对象，访问麻烦。 <img src="https://img.tsh520.cn/file/blog/article/file-20260311004521920.png" alt=""></li><li>解决方案：使用类变量。 <ul><li>定义语法：访问修饰符 static 数据类型 变量名; (推荐)</li><li>特点： <ol><li>被该类的所有对象实例共享。</li><li>在类加载时就初始化生成。</li><li>生命周期随类的加载而开始，随类的消亡而销毁。</li></ol></li><li>访问方式： <ul><li>类名.类变量名 (推荐)</li><li>对象名.类变量名</li></ul></li><li>内存布局：static变量是对象共享的（具体位置与JDK版本有关，可能在堆或方法区，共识是共享的）。</li></ul></li></ul><h3 id="_2-类方法-静态方法" tabindex="-1">2. 类方法（静态方法） <a class="header-anchor" href="#_2-类方法-静态方法" aria-label="Permalink to &quot;2. 类方法（静态方法）&quot;">​</a></h3><ul><li>定义语法：访问修饰符 static 返回类型 方法名()</li><li>调用方式：类名.类方法名 或 对象名.类方法名。</li><li>经典使用场景：工具类方法（如Math、Arrays中的方法）。当方法中不涉及任何和对象相关的成员时，可设计为静态方法，提高效率。</li><li>注意事项与细节： <ol><li>类方法和普通方法都随类加载而加载，结构信息存储在方法区。</li><li>类方法中无this参数；普通方法中隐含着this参数。</li><li>核心口诀：静态方法只能访问静态成员（静态变量、静态方法）。普通成员方法既可以访问非静态成员，也可以访问静态成员。</li><li>类方法中<strong>不能使用this和super</strong>关键字。</li><li>静态方法可以通过类名调用；普通方法必须通过对象名调用。</li></ol></li></ul><h2 id="二、理解main方法语法" tabindex="-1">二、理解main方法语法 <a class="header-anchor" href="#二、理解main方法语法" aria-label="Permalink to &quot;二、理解main方法语法&quot;">​</a></h2><ul><li>public static void main(String[] args) {}</li><li>深入理解： <ol><li>main方法由Java虚拟机(JVM)调用。</li><li>public: JVM需要调用，访问权限必须公开。</li><li>static: JVM调用时不必创建对象。</li><li>void: 无返回值给JVM。</li><li>String[] args: 接收命令行参数。</li></ol></li><li>在main方法中的访问规则： <ol><li>可以直接访问本类的静态成员。</li><li>不能直接访问本类的非静态成员，必须创建对象后通过对象访问。</li></ol></li></ul><h2 id="三、代码块" tabindex="-1">三、代码块 <a class="header-anchor" href="#三、代码块" aria-label="Permalink to &quot;三、代码块&quot;">​</a></h2><ul><li>基本介绍：属于类的成员，类似于方法，将逻辑语句封装在{}中。没有方法名、返回、参数，在加载类或创建对象时隐式调用。</li><li>基本语法：</li></ul><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[修饰符] {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 逻辑语句</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><ul><li>好处：是对构造器的补充，可将多个构造器中的重复语句抽取到初始化块中，提高代码重用性。</li><li>使用细节与执行顺序（非常重要！）： <ol><li>静态代码块：在类加载时执行，且只执行一次。可以初始化静态属性。</li><li>普通代码块：在每次创建对象时执行，在构造器之前执行。</li><li>执行顺序（继承关系下）： <ul><li>父类静态代码块 -&gt; 子类静态代码块 -&gt; 父类普通代码块 -&gt; 父类构造器 -&gt; 子类普通代码块 -&gt; 子类构造器。</li></ul></li><li>普通代码块只能直接调用本类的静态成员，不能调用非静态成员（因为此时对象可能还未完全初始化）。</li></ol></li></ul><h2 id="四、单例设计模式" tabindex="-1">四、单例设计模式 <a class="header-anchor" href="#四、单例设计模式" aria-label="Permalink to &quot;四、单例设计模式&quot;">​</a></h2><ul><li>设计模式：在大量实践中总结出的优选代码结构、编程风格和解决问题的思考方式。</li><li>单例模式：保证在整个软件系统中，对某个类只能存在一个对象实例，并提供一个获取该实例的全局访问点。</li><li>实现步骤： <ol><li>构造器私有化（防止外部new）。</li><li>类的内部创建对象。</li><li>向外暴露一个公共的静态方法 (getInstance) 来获取该对象。</li></ol></li><li>两种实现方式： <ul><li>饿汉式：类加载时就创建对象实例。 <ul><li>优点：线程安全（天然）。</li><li>缺点：可能造成资源浪费（如果实例一直未被使用）。</li></ul></li><li>懒汉式：使用时才创建对象实例。 <ul><li>优点：避免资源浪费。</li><li>缺点：存在线程安全问题（后续线程部分解决）。</li></ul></li></ul></li><li>应用实例：java.lang.Runtime 是经典的单例模式。</li></ul><h2 id="五、final关键字" tabindex="-1">五、final关键字 <a class="header-anchor" href="#五、final关键字" aria-label="Permalink to &quot;五、final关键字&quot;">​</a></h2><ul><li>含义：最终的。可以修饰类、属性、方法和局部变量。</li><li>使用场景： <ol><li>修饰类：该类不能被继承（如String类）。</li><li>修饰方法：该方法不能被重写/覆盖。</li><li>修饰属性：该属性变为常量，值必须初始化且之后不能修改。</li><li>修饰局部变量：该局部变量值不能修改。</li></ol></li><li>使用细节： <ol><li>final修饰的属性（常量）命名一般用XX_XX_XX（大写+下划线）。</li><li>final属性必须赋初值，赋值位置可选： <ul><li>定义时。</li><li>在构造器中。</li><li>在代码块中。</li></ul></li><li>如果final修饰的属性是静态的，则初始化位置只能是： <ul><li>定义时。</li><li>在静态代码块中。（不能在构造器中）</li></ul></li><li>final类不能继承，但可以实例化对象。</li><li>含有final方法的非final类，该方法可以被继承，但不能被重写。</li></ol></li></ul><h2 id="六、抽象类" tabindex="-1">六、抽象类 <a class="header-anchor" href="#六、抽象类" aria-label="Permalink to &quot;六、抽象类&quot;">​</a></h2><ul><li>提出问题：父类方法需要声明，但无法确定具体实现（如Animal的eat方法）。 <img src="https://img.tsh520.cn/file/blog/article/file-20260311004545694.png" alt=""></li><li>解决之道：使用abstract关键字。 <ul><li>abstract修饰类 -&gt; 抽象类。</li><li>abstract修饰方法 -&gt; 抽象方法（没有方法体）。</li></ul></li><li>介绍：抽象类的价值更多在于设计，让子类继承并实现其抽象方法。是框架和设计模式中常用的知识点。</li><li>注意事项与细节： <ol><li>抽象类不能被实例化。</li><li>抽象类不一定包含abstract方法。但一旦包含abstract方法，该类必须声明为abstract。</li><li>abstract只能修饰类和方法，不能修饰属性和其他。</li><li>抽象类本质还是类，可以有任意成员（属性、方法、构造器、代码块等）。</li><li>如果一个类继承了抽象类，则它必须实现父类的所有抽象方法，除非它自己也声明为abstract类。</li><li>抽象方法不能使用private、final和static修饰，因为这些关键字与重写相违背。</li></ol></li></ul><h2 id="七、抽象类最佳实践——模板设计模式" tabindex="-1">七、抽象类最佳实践——模板设计模式 <a class="header-anchor" href="#七、抽象类最佳实践——模板设计模式" aria-label="Permalink to &quot;七、抽象类最佳实践——模板设计模式&quot;">​</a></h2><ul><li>介绍：抽象类体现了一种模板模式设计，作为多个子类的通用模板。子类在抽象类基础上扩展，但总体上保留抽象类的行为方式。</li><li>解决问题：当功能内部一部分实现是确定的，一部分不确定时。将不确定的部分暴露为抽象方法，让子类实现。</li><li>最佳实践案例：统计不同任务执行的时间。 <ul><li>在抽象父类 (Template) 中，定义计算时间的通用方法 (calculateTime)。</li><li>将具体任务 (job) 声明为抽象方法，由子类实现。</li><li>这样既统一了计时逻辑，又保留了子类任务的灵活性。</li></ul></li></ul><h2 id="八、接口-interface" tabindex="-1">八、接口 (interface) <a class="header-anchor" href="#八、接口-interface" aria-label="Permalink to &quot;八、接口 (interface)&quot;">​</a></h2><ul><li>为什么有接口：实现统一规范，解决高内聚低耦合的设计需求（类似于现实中的USB接口）。</li><li>快速入门：接口是更加抽象的抽象类。在JDK7.0及以前，接口中所有方法都是抽象方法（没有方法体）。JDK8.0后，接口可以有静态方法、默认方法（有具体实现）。</li><li>基本语法：</li></ul><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 接口名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 属性 (默认 public static final)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 方法 (默认 public abstract)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 类名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> implements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 接口 {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 必须实现接口的所有抽象方法</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>核心定义</p><ul><li>本质：一种行为规范（契约），定义了一组方法签名，但不包含具体实现（Java 8 之前）。</li><li>实例化：不能被实例化（new），不能有构造函数。</li><li>继承关系：类通过 implements 实现接口；接口通过 extends 继承其他接口（支持多重继承）。 成员规则速查表</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">成员类型</th><th style="text-align:left;">默认修饰符</th><th style="text-align:left;">关键限制</th><th style="text-align:left;">备注</th></tr></thead><tbody><tr><td style="text-align:left;">变量</td><td style="text-align:left;">public static final</td><td style="text-align:left;">必须是常量，声明即初始化</td><td style="text-align:left;">无法在实现类中修改</td></tr><tr><td style="text-align:left;">抽象方法</td><td style="text-align:left;">public abstract</td><td style="text-align:left;">实现类必须重写</td><td style="text-align:left;">核心契约</td></tr><tr><td style="text-align:left;">默认方法</td><td style="text-align:left;">default(Java 8+)</td><td style="text-align:left;">可有具体实现，可被重写</td><td style="text-align:left;">解决多继承冲突需显式调用Interface.super.method()</td></tr><tr><td style="text-align:left;">静态方法</td><td style="text-align:left;">static(Java 8+)</td><td style="text-align:left;">不可被继承或重写</td><td style="text-align:left;">只能通过接口名.方法()调用</td></tr><tr><td style="text-align:left;">私有方法</td><td style="text-align:left;">private(Java 9+)</td><td style="text-align:left;">仅接口内部可见</td><td style="text-align:left;">用于 default/static 方法的代码复用</td></tr></tbody></table><h3 id="三大关键陷阱与细节" tabindex="-1">三大关键陷阱与细节 <a class="header-anchor" href="#三大关键陷阱与细节" aria-label="Permalink to &quot;三大关键陷阱与细节&quot;">​</a></h3><ol><li>多继承冲突 场景：类实现了两个接口，且这两个接口有同名的 default 方法。 结果：编译报错。 解决：实现类必须重写该方法，并使用 InterfaceName.super.methodName() 指定调用哪一个父接口的逻辑。 优先级规则：抽象方法 &gt; 默认方法。如果一个是抽象方法，一个是默认方法，实现类必须实现抽象方法（默认方法自动失效）。</li><li>访问权限控制 对外：接口中的抽象方法和默认方法本质上都是 public。</li><li>重写规则：实现类在重写接口方法时，必须使用 public 修饰符，不能降低访问权限（如改为 protected或private）。</li><li>函数式接口 (Functional Interface) 定义：只包含一个抽象方法的接口。 用途：Lambda 表达式的基础。</li><li>注解：推荐加上 @FunctionalInterface，编译器会检查是否只有一个抽象方法（允许有多个 default/static 方法）。</li></ol><h3 id="最佳实践建议" tabindex="-1">最佳实践建议 <a class="header-anchor" href="#最佳实践建议" aria-label="Permalink to &quot;最佳实践建议&quot;">​</a></h3><ol><li>接口隔离：保持接口小而专一，避免“胖接口”。</li><li>向后兼容：升级旧接口时，优先使用 default 方法添加新功能，避免破坏现有实现类。</li><li>代码复用：如果多个接口需要共享逻辑，优先考虑抽象类；如果必须用接口，利用 Java 9 的 private 方法在接口内部提取公共逻辑。</li><li>常量管理：虽然接口可以定义常量，但不要把接口当作纯粹的常量容器（Constant Interface 反模式），建议使用类或枚举来管理常量。</li></ol><h2 id="九、内部类" tabindex="-1">九、内部类 <a class="header-anchor" href="#九、内部类" aria-label="Permalink to &quot;九、内部类&quot;">​</a></h2><h3 id="_1-局部内部类" tabindex="-1">1. 局部内部类 <a class="header-anchor" href="#_1-局部内部类" aria-label="Permalink to &quot;1. 局部内部类&quot;">​</a></h3><ul><li>定义：定义在方法体、构造器或代码块内部。</li><li>特点： <ol><li>可以直接访问外部类的所有成员（包含私有）。</li><li>不能使用访问修饰符（public/private）或 static（地位如同局部变量），但可用final修饰。</li><li>作用域仅限当前代码块，外部不可见。</li><li>外部其他类不能访问局部内部类。</li><li>如果外部类和内部类成员重名，默认就近原则，访问外部类成员用外部类名.this.成员。</li><li>访问局部变量限制：只能访问 final 或 effectively final（初始化后未修改）的局部变量。 <ul><li>原理：生命周期不一致（栈 vs 堆），Java 通过值复制实现闭包。</li></ul></li></ol></li><li>适用场景：逻辑仅在当前方法内使用，避免污染类结构。</li></ul><h3 id="_2-匿名内部类-极其重要" tabindex="-1">2. 匿名内部类（极其重要！） <a class="header-anchor" href="#_2-匿名内部类-极其重要" aria-label="Permalink to &quot;2. 匿名内部类（极其重要！）&quot;">​</a></h3><p>定义：没有类名的内部类，定义即实例化。 本质：同时是一个类、一个对象。 特点：</p><ul><li>本质是局部内部类的特例。</li><li>必须继承一个父类或实现一个接口。</li><li>不能定义构造函数（无名），不能定义静态成员。</li><li>this 指向匿名类实例本身。 语法：</li></ul><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 类</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">接口 (参数列表) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 类体（重写方法或实现方法）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>现代替代：若是函数式接口，优先使用 Lambda 表达式。</p><h3 id="_3-成员内部类" tabindex="-1">3. 成员内部类 <a class="header-anchor" href="#_3-成员内部类" aria-label="Permalink to &quot;3. 成员内部类&quot;">​</a></h3><ul><li>定义：位于外部类内部，与成员变量同级，无 static 修饰。</li><li>特点： <ol><li>可访问外部类所有成员（含私有）</li><li>不能定义静态成员（static final 常量除外）。</li><li>隐式持有外部类实例引用 (Outer.this)。</li><li>可以添加任意访问修饰符（地位是一个成员）。</li><li>作用域为整个类体。</li><li>外部其他类访问成员内部类： <ul><li>外部类.内部类 引用 = 外部类对象.new 内部类();</li><li>通过外部类提供的返回内部类对象的方法。</li></ul></li></ol></li></ul><p>实例化语法：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Outer outer = new Outer();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Outer.Inner inner = outer.new Inner(); // 必须依赖外部类实例</span></span></code></pre></div><p>访问同名成员：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Outer.this.variableName; // 显式访问外部类成员</span></span></code></pre></div><h3 id="_4-静态内部类" tabindex="-1">4. 静态内部类 <a class="header-anchor" href="#_4-静态内部类" aria-label="Permalink to &quot;4. 静态内部类&quot;">​</a></h3><ul><li>定义：位于外部类内部，使用 static 修饰。</li><li>特点： <ol><li>可以直接访问外部类的所有静态成员（含私有），不能直接访问非静态成员。</li><li>可以定义静态成员。</li><li>独立于外部类存在。</li><li>不持有外部类实例引用（节省内存，防泄漏）。</li><li>可以添加任意访问修饰符。</li><li>作用域为整个类体。</li><li>外部其他类访问静态内部类： <ul><li>外部类.内部类 引用 = new 外部类.内部类(); （通过类名直接访问）</li><li>通过外部类提供的返回静态内部类对象的方法。 实例化语法：</li></ul></li></ol></li></ul><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Outer.StaticInner inner = new Outer.StaticInner(); // 直接 new</span></span></code></pre></div><ul><li>典型应用： <ul><li>单例模式（静态内部类单例，线程安全且懒加载）。</li><li>工具类嵌套。</li></ul></li></ul><h3 id="核心对比速查表" tabindex="-1">核心对比速查表 <a class="header-anchor" href="#核心对比速查表" aria-label="Permalink to &quot;核心对比速查表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">成员内部类</th><th style="text-align:left;">静态内部类</th><th style="text-align:left;">局部内部类</th><th style="text-align:left;">匿名内部类</th></tr></thead><tbody><tr><td style="text-align:left;">static 修饰</td><td style="text-align:left;">❌</td><td style="text-align:left;">✅</td><td style="text-align:left;">❌</td><td style="text-align:left;">❌</td></tr><tr><td style="text-align:left;">外部类实例依赖</td><td style="text-align:left;">必须</td><td style="text-align:left;">不需要</td><td style="text-align:left;">视情况 (访问非静态需依赖)</td><td style="text-align:left;">视情况</td></tr><tr><td style="text-align:left;">访问外部私有成员</td><td style="text-align:left;">✅</td><td style="text-align:left;">仅静态成员</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;">访问局部变量</td><td style="text-align:left;">N/A</td><td style="text-align:left;">N/A</td><td style="text-align:left;">仅 final/effectively final</td><td style="text-align:left;">仅 final/effectively final</td></tr><tr><td style="text-align:left;">定义静态成员</td><td style="text-align:left;">❌ (除常量)</td><td style="text-align:left;">✅</td><td style="text-align:left;">❌</td><td style="text-align:left;">❌</td></tr><tr><td style="text-align:left;">访问修饰符</td><td style="text-align:left;">public/private等</td><td style="text-align:left;">public/private等</td><td style="text-align:left;">无</td><td style="text-align:left;">无</td></tr><tr><td style="text-align:left;">主要用途</td><td style="text-align:left;">强耦合业务逻辑</td><td style="text-align:left;">解耦工具/单例</td><td style="text-align:left;">临时逻辑封装</td><td style="text-align:left;">一次性回调/监听</td></tr></tbody></table><h3 id="lambda-vs-匿名内部类" tabindex="-1">Lambda vs 匿名内部类 <a class="header-anchor" href="#lambda-vs-匿名内部类" aria-label="Permalink to &quot;Lambda vs 匿名内部类&quot;">​</a></h3><ul><li>推荐：Java 8+ 实现函数式接口时，首选 Lambda。</li><li>区别： <ul><li>Lambda 更简洁，编译器优化更好（复用 class 文件）。</li><li>this 指向不同：Lambda 的 this 指向外部类；匿名内部类的 this 指向内部类。</li></ul></li></ul>`,51)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
